NEW=[]
META={}
for key,family,title,seq,copy,speech in DATA:
    lines=speech.split("|")
    if len(seq)!=10 or len(lines)!=10:raise ValueError((key,seq,len(lines)))
    rows=[]
    for i,(code,line) in enumerate(zip(seq,lines)):
        h,p,s=TARGETS[code]
        rows.append((title if i==0 else h,p,s,line))
    NEW.append(Topic(key,caption(copy,{"auto":"Autószerviz","menu":"DigitálisÉtlap","salon":"Szépségszalon","crm":"Ügyfélkezelés","web":"ÜzletiWeboldal"}[family]),tuple(rows)))
    META[key]={"family":family,"title":title,"style":family}
NEW=tuple(NEW)
TOPICS=EXISTING+NEW
def validate_catalogue():
    from heygen_budget_v126 import MAX_BYTES
    from daily_catalogue_v124 import plan
    from video_dedup import script_similarity,script_text
    from itertools import combinations
    assert len(NEW)==35 and len(TOPICS)==51 and len({t.key for t in TOPICS})==51
    for t in TOPICS:
        text=" ".join(r[3] for r in t.scenes)
        assert len(t.scenes)==10 and 500<=len(text)<=1000 and len(text.encode("utf8"))<=MAX_BYTES,(t.key,len(text.encode("utf8")))
        assert "AI-narráció" in t.text
        print("V1266_TOPIC",t.key,len(text.encode("utf8")),flush=True)
    scripts={t.key:script_text(plan(t)) for t in TOPICS}
    for a,b in combinations(TOPICS,2):
        sim=script_similarity(scripts[a.key],scripts[b.key])
        assert sim<.80,(a.key,b.key,sim)
    print("V1266_CATALOGUE_PASS 51 topics, 350 new scenes, all script pairs",flush=True)
def manifest():return {t.key:t.text for t in NEW}
if __name__=="__main__":validate_catalogue()
